using HamiChap_MES_ERP.Data;
using HamiChap_MES_ERP.Models.Inventory;
using HamiChap_MES_ERP.Models.Sales.Enums;
using Microsoft.EntityFrameworkCore;

namespace HamiChap_MES_ERP.Models.Sales;

/// <summary>
/// Synchronizes the one item generated by a job editor with its corresponding
/// quotation line while the quotation is still Draft or RevisionRequired.
/// This preserves distinct quotation lines/proofs even when jobs reuse ItemId.
/// Call from the same transaction that saves the job specifications.
/// </summary>
public static class SalesJobQuotationLineSync
{
    public static async Task SyncAsync(
        ApplicationDbContext db,
        SalesRequest request,
        Item finishedProduct,
        decimal quantity)
    {
        var quotation = await db.Quotations
            .Include(x => x.Lines)
            .FirstOrDefaultAsync(x =>
                x.SalesRequestId == request.Id ||
                x.Lines.Any(l => l.SourceRequestId == request.Id));

        if (quotation is null)
        {
            if (request.Status == SalesRequestStatus.QuotationCreated)
                throw new InvalidOperationException("The quotation linked to this job was not found.");
            return;
        }

        if (quotation.Status is not (QuotationStatus.Draft or QuotationStatus.RevisionRequired))
            throw new InvalidOperationException(
                "Job specifications cannot change after quotation approval.");

        // Existing multi-job quotations identify the exact originating job.
        var lines = quotation.Lines.Where(x => x.SourceRequestId == request.Id).ToList();

        // The old data model had no SourceRequestId on quotation lines.
        // Only infer the link if the legacy quotation has exactly one line.
        if (lines.Count == 0 && quotation.SalesRequestId == request.Id &&
            quotation.Lines.Count == 1 &&
            quotation.Lines.First().SourceRequestId == null)
        {
            var legacyLine = quotation.Lines.First();
            legacyLine.SourceRequestId = request.Id;
            lines.Add(legacyLine);
        }

        if (lines.Count != 1)
            throw new InvalidOperationException(
                "The job has no unique quotation line. Resolve its link before editing.");

        var quoteLine = lines[0];
        if (quoteLine.ItemId != finishedProduct.Id)
        {
            // The old item was priced separately. Do not silently reuse that
            // price for a different design.
            quoteLine.ItemId = finishedProduct.Id;
            quoteLine.Item = finishedProduct;
            quoteLine.UnitPrice = 0;
        }
        quoteLine.Quantity = quantity;
        quotation.FinalAmount = quotation.Lines.Sum(x => x.TotalPrice);
    }
}
